import{_ as t,o as r,c as a,a2 as d}from"./chunks/framework.CnJ-JtFX.js";const g=JSON.parse('{"title":"EP.16 从零开始，先画一张架构图","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.16-mini-lowcode-architecture.md","filePath":"comics/EP.16-mini-lowcode-architecture.md","lastUpdated":1792683644000}'),i={name:"comics/EP.16-mini-lowcode-architecture.md"};function o(n,e,l,s,h,c){return r(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="ep-16-从零开始-先画一张架构图" tabindex="-1">EP.16 从零开始，先画一张架构图 <a class="header-anchor" href="#ep-16-从零开始-先画一张架构图" aria-label="Permalink to &quot;EP.16 从零开始，先画一张架构图&quot;">​</a></h1><blockquote><p>对应章节：<a href="./../guide/16-mini-lowcode-architecture">guide/16-mini-lowcode-architecture</a></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><ol><li><strong>面对空白画布</strong>：像素酱决定不依赖 amis / Formily / lowcode-engine 等商业框架，从零手写一个教学级 mini 低代码引擎。第一步不是写代码，而是画架构图。</li><li><strong>六大模块架构图</strong>：Schema → Renderer → Designer → History → Plugin → Codegen，六个模块各管一摊，构成完整的低代码引擎。</li><li><strong>为什么要自己写</strong>：标签君质疑现成框架那么多为什么要从零写，像素酱回答「理解原理才能用好工具」，白盒才能真正掌握。</li><li><strong>本质总结</strong>：码叔一锤定音——低代码引擎的本质是「数据驱动视图」，Schema 是数据，Renderer 把数据变成视图。</li></ol><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="第一格-从零搭的价值" tabindex="-1">第一格：从零搭的价值 <a class="header-anchor" href="#第一格-从零搭的价值" aria-label="Permalink to &quot;第一格：从零搭的价值&quot;">​</a></h3><p>商业框架（amis、Formily、lowcode-engine、tmagic-editor、GrapesJS）都是黑盒。用黑盒能快速出活，但遇到框架边界外的需求会束手无策。自己从零写一个 mini 引擎，目的不是造轮子，而是<strong>理解轮子的原理</strong>。</p><p><strong>关键认知</strong>：教学级引擎不追求生产级完备性，只追求「跑通全链路 + 每一行代码都能解释清楚」。</p><h3 id="第二格-六大模块职责" tabindex="-1">第二格：六大模块职责 <a class="header-anchor" href="#第二格-六大模块职责" aria-label="Permalink to &quot;第二格：六大模块职责&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模块</th><th>职责</th><th>输入</th><th>输出</th></tr></thead><tbody><tr><td>Schema</td><td>描述页面结构的 JSON 数据</td><td>—</td><td>JSON 树</td></tr><tr><td>Renderer</td><td>递归遍历 Schema，输出真实 DOM</td><td>Schema 节点</td><td>Vue 组件 / DOM</td></tr><tr><td>Designer</td><td>可视化拖拽，修改 Schema</td><td>用户操作</td><td>Schema 变更</td></tr><tr><td>History</td><td>命令模式，支持撤销重做</td><td>操作命令</td><td>undo / redo</td></tr><tr><td>Plugin</td><td>setup(api) 扩展能力</td><td>插件函数</td><td>扩展后的引擎</td></tr><tr><td>Codegen</td><td>把 Schema 导出成可运行代码</td><td>Schema</td><td>.vue + .json</td></tr></tbody></table><p>六个模块的关系是线性流水线：Schema 是数据源，Renderer 消费 Schema 生成视图，Designer 修改 Schema，History 记录 Schema 的变更，Plugin 给所有模块打扩展点，Codegen 把 Schema 导出为产物。</p><h3 id="第三格-理解原理才能用好工具" tabindex="-1">第三格：理解原理才能用好工具 <a class="header-anchor" href="#第三格-理解原理才能用好工具" aria-label="Permalink to &quot;第三格：理解原理才能用好工具&quot;">​</a></h3><p>自己写一遍 Renderer，就知道 lowcode-engine 的渲染引擎在解决什么问题（递归、表达式、上下文、生命周期）；自己写一遍 Designer，就知道拖拽落点的判断逻辑有多复杂（before / after / inside、禁止循环、容器判断）。</p><p><strong>黑盒 vs 白盒</strong>：黑盒用久了会失去判断力——遇到问题只会查文档、提 issue。白盒让你知道问题的根因在哪一层，能直接定位和修复。</p><h3 id="第四格-数据驱动视图" tabindex="-1">第四格：数据驱动视图 <a class="header-anchor" href="#第四格-数据驱动视图" aria-label="Permalink to &quot;第四格：数据驱动视图&quot;">​</a></h3><p>低代码引擎的核心抽象是<strong>数据驱动视图</strong>：</p><ul><li>Schema 是纯数据（JSON），可序列化、可存储、可传输；</li><li>Renderer 是纯函数（给定 Schema + 上下文 → 输出视图），不持有状态；</li><li>Designer 不直接操作 DOM，只修改 Schema，Renderer 自动响应变更。</li></ul><p>这个抽象把「页面」从「代码」变成了「数据」，从而获得了可视化编辑、撤销重做、出码、跨端渲染等一系列能力。</p><h2 id="坑点清单" tabindex="-1">坑点清单 <a class="header-anchor" href="#坑点清单" aria-label="Permalink to &quot;坑点清单&quot;">​</a></h2><ol><li><strong>一开始就追求生产级</strong>：教学引擎如果追求和 lowcode-engine 一样的完备性，会陷入无穷无尽的边界处理。先跑通最小链路，再逐步加能力。</li><li><strong>模块边界模糊</strong>：Renderer 和 Designer 都碰 Schema，如果不明确谁负责「渲染」谁负责「修改」，代码会耦合。原则：Renderer 只读 Schema，Designer 只写 Schema。</li><li><strong>忽视 Plugin 的扩展点设计</strong>：Plugin 不是事后加的，架构阶段就要预留 setup(api) 钩子，否则后期扩展要改核心代码。</li><li><strong>Schema 设计过早抽象</strong>：第一版 Schema 只需要 type / children / props 三个字段，不要一开始就设计复杂的生命周期、数据源、表达式。</li><li><strong>把 History 当可选模块</strong>：没有撤销重做的设计器是不可用的，History 必须和 Designer 一起设计，不能事后补。</li><li><strong>Codegen 放到最后才想</strong>：出码能力决定了 Schema 的字段设计（哪些字段要保留、哪些可以丢弃），架构阶段就要考虑出码产物的格式。</li></ol><h2 id="自测" tabindex="-1">自测 <a class="header-anchor" href="#自测" aria-label="Permalink to &quot;自测&quot;">​</a></h2><details><summary><b>1. 为什么要从零写一个 mini 低代码引擎，而不是直接用现成框架？</b></summary><p>核心目的是<strong>理解原理</strong>：</p><ul><li>现成框架是黑盒，遇到边界外的需求只能查文档、提 issue，无法定位根因；</li><li>自己写一遍 Renderer，就知道递归渲染、表达式求值、上下文传递的坑在哪；</li><li>自己写一遍 Designer，就知道拖拽落点判断（before / after / inside）有多复杂；</li><li>白盒认知让你在用现成框架时能精准选型、精准排查问题。</li></ul><p>教学级引擎不追求生产级完备性，只追求「跑通全链路 + 每一行代码都能解释」。</p></details><details><summary><b>2. mini-lowcode 的六大模块分别是什么？各自的输入输出是什么？</b></summary><table tabindex="0"><thead><tr><th>模块</th><th>输入</th><th>输出</th></tr></thead><tbody><tr><td>Schema</td><td>—</td><td>描述页面结构的 JSON 树</td></tr><tr><td>Renderer</td><td>Schema 节点 + 上下文</td><td>渲染出的 Vue 组件 / DOM</td></tr><tr><td>Designer</td><td>用户拖拽操作</td><td>Schema 的变更（增删改）</td></tr><tr><td>History</td><td>操作命令（Command）</td><td>undo / redo 能力</td></tr><tr><td>Plugin</td><td>setup(api) 函数</td><td>扩展后的引擎能力</td></tr><tr><td>Codegen</td><td>Schema</td><td>.vue 文件 + .json 配置</td></tr></tbody></table><p>六个模块构成线性流水线：Schema 是数据源，Renderer 消费 Schema 生成视图，Designer 修改 Schema，History 记录变更，Plugin 打扩展点，Codegen 导出产物。</p></details><details><summary><b>3. 为什么说低代码引擎的本质是「数据驱动视图」？</b></summary><p>因为低代码引擎的核心抽象是把「页面」从「代码」变成「数据」：</p><ol><li><strong>Schema 是纯数据</strong>：JSON 格式，可序列化、可存储、可传输、可版本管理；</li><li><strong>Renderer 是纯函数</strong>：给定 Schema + 上下文，输出视图，不持有状态；</li><li><strong>Designer 只改数据不改 DOM</strong>：拖拽操作修改 Schema，Renderer 自动响应变更重新渲染。</li></ol><p>这个抽象带来了一系列能力：可视化编辑（改 Schema）、撤销重做（回滚 Schema）、出码（Schema 转代码）、跨端渲染（同一份 Schema 给不同端的 Renderer）。如果没有「数据驱动视图」这个抽象，这些能力都无法实现。</p></details>',24)])])}const u=t(i,[["render",o]]);export{g as __pageData,u as default};
